func (v ForkValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	var upstream basetypes.ObjectValue

	if v.Upstream.IsNull() {
		upstream = types.ObjectNull(
			UpstreamValue{}.AttributeTypes(ctx),
		)
	}

	if v.Upstream.IsUnknown() {
		upstream = types.ObjectUnknown(
			UpstreamValue{}.AttributeTypes(ctx),
		)
	}

	if !v.Upstream.IsNull() && !v.Upstream.IsUnknown() {
		upstream = types.ObjectValueMust(
			UpstreamValue{}.AttributeTypes(ctx),
			v.Upstream.Attributes(),
		)
	}

	attributeTypes := map[string]attr.Type{
		"ahead":        basetypes.Int64Type{},
		"behind":       basetypes.Int64Type{},
		"kind":         basetypes.StringType{},
		"purpose":      basetypes.StringType{},
		"relationship": basetypes.StringType{},
		"state":        basetypes.StringType{},
		"upstream": basetypes.ObjectType{
			AttrTypes: UpstreamValue{}.AttributeTypes(ctx),
		},
		"visibility_ceiling": basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"ahead":              v.Ahead,
			"behind":             v.Behind,
			"kind":               v.Kind,
			"purpose":            v.Purpose,
			"relationship":       v.Relationship,
			"state":              v.State,
			"upstream":           upstream,
			"visibility_ceiling": v.VisibilityCeiling,
		})

	return objVal, diags
}

func (v ForkValue) Equal(o attr.Value) bool {
	other, ok := o.(ForkValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Ahead.Equal(other.Ahead) {
		return false
	}

	if !v.Behind.Equal(other.Behind) {
		return false
	}

	if !v.Kind.Equal(other.Kind) {
		return false
	}

	if !v.Purpose.Equal(other.Purpose) {
		return false
	}

	if !v.Relationship.Equal(other.Relationship) {
		return false
	}

	if !v.State.Equal(other.State) {
		return false
	}

	if !v.Upstream.Equal(other.Upstream) {
		return false
	}

	if !v.VisibilityCeiling.Equal(other.VisibilityCeiling) {
		return false
	}

	return true
}

